185→Props: none (fetches its own data via polling)
186→
187→```tsx
188→import { useCallback, useEffect, useRef, useState } from 'react';
189→import { migrationApi, type MigrationStatus } from '../../lib/api/migration';
190→
191→export function MigrationProgress() {
192→  const [migration, setMigration] = useState<MigrationStatus | null>(null);
193→  const [showCancelConfirm, setShowCancelConfirm] = useState(false);
194→  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);
195→
196→  const fetchStatus = useCallback(async () => {
197→    const status = await migrationApi.getStatus();
198→    setMigration(status);
199→    // Stop polling when terminal state reached
200→    if (status && ['completed', 'failed', 'cancelled'].includes(status.status)) {
201→      if (pollRef.current) {
202→        clearInterval(pollRef.current);
203→        pollRef.current = null;
204→      }
205→    }
206→  }, []);
207→
208→  // Poll every 5 seconds when migration is active
209→  useEffect(() => {
210→    fetchStatus();
211→    pollRef.current = setInterval(fetchStatus, 5000);
212→    return () => {
213→      if (pollRef.current) clearInterval(pollRef.current);
214→    };
215→  }, [fetchStatus]);
216→
217→  if (!migration || migration.status === 'cancelled') return null;
218→
219→  const percentage =
220→    migration.totalCids > 0 ? (migration.migratedCids / migration.totalCids) * 100 : 0;
221→
222→  const isActive = migration.status === 'running' || migration.status === 'pending';
223→  const isPaused = migration.status === 'paused';
224→  const isComplete = migration.status === 'completed';
225→
226→  const handlePause = async () => {
227→    await migrationApi.pause(migration.id);
228→    fetchStatus();
229→  };
230→
231→  const handleResume = async () => {
232→    await migrationApi.resume(migration.id);
233→    fetchStatus();
234→  };
235→
236→  const handleCancel = async () => {
237→    await migrationApi.cancel(migration.id);
238→    setShowCancelConfirm(false);
239→    fetchStatus();
240→  };
241→
242→  return (
243→    <div className="migration-progress">
244→      <h3 className="settings-section-heading">{'// pin migration'}</h3>
245→      <p className="settings-section-description">
246→        {
247→          'migrate existing pins between providers. data is transferred via tee -- your encryption keys are never exposed.'
248→        }
249→      </p>
250→
251→      {/* Progress bar */}
252→      <div
253→        className="migration-progress-bar"
254→        role="progressbar"
255→        aria-valuenow={migration.migratedCids}
256→        aria-valuemin={0}
257→        aria-valuemax={migration.totalCids}
258→        aria-label="Pin migration progress"
259→      >
260→        <div
261→          className="migration-progress-fill"
262→          style={{ width: `${Math.min(percentage, 100)}%` }}
263→        />
264→      </div>
265→
266→      {/* Progress text */}
267→      {isComplete ? (
268→        <p className="migration-progress-text migration-complete">
269→          {`> migration complete. ${migration.totalCids} pins transferred.`}
270→        </p>
271→      ) : (
272→        <p className="migration-progress-text">
273→          {`migrating: ${migration.migratedCids}/${migration.totalCids} pins`}
274→        </p>
275→      )}
276→
277→      {/* Failed count */}
278→      {migration.failedCids > 0 && (
279→        <p className="migration-failed-text">{`${migration.failedCids} pins failed`}</p>
280→      )}
281→
282→      {/* Controls */}
283→      {(isActive || isPaused) && (
284→        <div className="migration-controls">
285→          {isActive && (
286→            <button type="button" className="storage-discard-btn" onClick={handlePause}>
287→              {'[--pause migration]'}
288→            </button>
289→          )}
290→          {isPaused && (
291→            <button type="button" className="storage-discard-btn" onClick={handleResume}>
292→              {'[--resume migration]'}
293→            </button>
294→          )}
295→
296→          {showCancelConfirm ? (
297→            <div className="migration-cancel-confirm">
298→              <p className="migration-cancel-text">
299→                {`cancel migration: ${migration.migratedCids}/${migration.totalCids} pins transferred. pins already migrated will remain on the new provider. cancel?`}
300→              </p>
301→              <button type="button" className="storage-discard-btn" onClick={handleCancel}>
302→                {'[--confirm cancel]'}
303→              </button>
304→              <button
305→                type="button"
306→                className="storage-discard-btn"
307→                onClick={() => setShowCancelConfirm(false)}
308→              >
309→                {'[--keep migrating]'}
310→              </button>
311→            </div>
312→          ) : (
313→            <button
314→              type="button"
315→              className="storage-discard-btn"
316→              onClick={() => setShowCancelConfirm(true)}
317→            >
318→              {'[--cancel migration]'}
319→            </button>
320→          )}
321→        </div>
322→      )}
323→    </div>
324→  );
325→}
326→```
