**3. Add private `pinWithMode` method to `packages/sdk/src/client.ts`:**

This method replaces the default `addToIpfs` call and is the sole IPFS pin entry point for all modes. It enforces the locked decisions: no CipherBox involvement for external+Kubo, fail hard on unreachable Kubo, CipherBox relay acceptable only for PSA (CID acquisition).

```typescript
/**
 * Pin encrypted data according to the configured pinning mode.
 * Returns { cid, size } regardless of mode.
 *
 * CRITICAL per user decisions:
 * - external+Kubo: encrypt -> KuboProvider.pin() DIRECTLY. No CipherBox relay.
 *   If Kubo unreachable, throw (no silent fallback).
 * - external+PSA: CipherBox relay to get CID (PSA is CID-reference-only),
 *   then PSA pinByCid, then unpin from CipherBox.
 * - dual: CipherBox primary (must succeed), external secondary (best-effort).
 * - cipherbox: standard addToIpfs unchanged.
 */
private async pinWithMode(
  encryptedData: Uint8Array,
  ctx: SdkContext,
  onProgress?: ProgressCallback
): Promise<{ cid: string; size: number; secondaryWarning?: string }> {
  const mode = this.config.pinningConfig?.mode ?? 'cipherbox';

  if (mode === 'cipherbox' || !this.externalProvider) {
    // Default: upload via CipherBox API relay
    const result = await sdkCore.addToIpfs(ctx, encryptedData, onProgress);
    return { cid: result.cid, size: result.size };
  }

  if (mode === 'external') {
    const ext = this.config.pinningConfig!.externalProvider!;

    if (ext.protocol === 'kubo') {
      // Direct upload to user's Kubo node -- NO CipherBox involvement at all.
      // If Kubo is unreachable, this throws. No silent fallback.
      // Per locked decision: "BYO-only mode: if user's node is unreachable,
      // upload fails with clear error -- no silent fallback to CipherBox"
      const result = await this.externalProvider.pin(encryptedData);
      // Register CID with API for advisory tracking only
      await sdkCore.registerCid(ctx, result.cid, result.size);
      return { cid: result.cid, size: result.size };
    }

    // PSA: upload to CipherBox relay first (PSA can't accept raw data -- it's
    // CID-reference-only per the spec), then tell PSA to pin the CID, then
    // unpin from CipherBox. This is the only acceptable CipherBox involvement
    // for external+PSA mode per RESEARCH.md Pattern 4.
    const relayResult = await sdkCore.addToIpfs(ctx, encryptedData, onProgress);
    try {
      await (this.externalProvider as any).pinByCid(relayResult.cid);
    } catch (err) {
      // PSA pin failed, but data is still on CipherBox node
      // Don't unpin from CipherBox -- leave it as fallback
      throw new Error(
        `External PSA pin failed: ${err instanceof Error ? err.message : String(err)}. Data remains on CipherBox node.`
      );
    }
    // PSA accepted the pin request -- unpin from CipherBox (async, best-effort)
    sdkCore.unpinFromIpfs(ctx, relayResult.cid).catch(() => {});
    // Register CID for advisory tracking
    await sdkCore.registerCid(ctx, relayResult.cid, relayResult.size);
    return { cid: relayResult.cid, size: relayResult.size };
  }

  // Dual mode: primary to CipherBox, secondary to external (best-effort)
  const primaryResult = await sdkCore.addToIpfs(ctx, encryptedData, onProgress);
  let secondaryWarning: string | undefined;
  try {
    const ext = this.config.pinningConfig!.externalProvider!;
    if (ext.protocol === 'kubo') {
      await this.externalProvider.pin(encryptedData);
    } else {
      await (this.externalProvider as any).pinByCid(primaryResult.cid);
    }
  } catch (err) {
    secondaryWarning = `mirror to ${this.config.pinningConfig?.externalProvider?.providerName ?? 'external node'} failed -- will retry`;
  }
  return { cid: primaryResult.cid, size: primaryResult.size, secondaryWarning };
}
```

