  const existing = await this.migrationRepository.findOne({
    where: {
      userId,
      status: In(['pending', 'running', 'paused']),
    },
  });
  if (existing) {
    throw new ConflictException('An active migration already exists. Cancel or wait for completion.');
  }
  // ... proceed with creation
}
